            "title": "Контрпример для смежных углов",
            "href": "/trainers/task19-trainer.html?card=prev-001",
            "instruction": "Прочитай утверждение, затем при необходимости открой модель. Измени один угол, сохранив смежность. Запиши две величины, опровергающие ошибочный общий вывод.",
            "finish": "Построй 1 контрпример и проверь ещё 2 карточки темы «Прямые и углы»."
